import six

from moler.device import DeviceFactory
from taf.rfrl.bts.devices.asir.generic_asir import GenericAsirHub
from taf.rfrl.bts.helpers.singleton import Singleton
from taf.rfrl.utilities.transfer_files import download_files
from taf.rfrl.utilities.tl_config import load_moler_configuration_from_tl
from taf.rfrl.utilities.test_config import get_log_path
from taf.rfrl.bts.common.tcpdump_collection import start_tcpdump_on_device, stop_tcpdump_on_device


class AsirHubLog(GenericAsirHub):
    """Class contains logs collecting keywords for BTS ASiR HUB"""

    def __init__(self, bts_type="GNB"):
        """
        Constructor of AsirHubLog class.
        """
        super(AsirHubLog, self).__init__(bts_type=bts_type)

    @load_moler_configuration_from_tl()
    def download_tcpdump_from_hub(self, log_file_name, bts_id=0, hub_id=0, log_dir=None, hub_log_dir="/tmp/logs",
                                  timeout=120):
        """
        Download pcap logs from HUB to local machine.

        :param log_file_name: name of the file logs will be saved to
        :param timeout: timeout for scp.
        :param log_dir: path to directory where tcpdump logs will be download
        :param hub_log_dir: path to directory where tcpdump logs will be moved before download
        :param bts_id:  BTS ID - related to TestLine configuration
        :param hub_id: HUB id - id related to Test Line configuration
        :return: directory where the logs are saved
        """
        if log_dir is None:
            log_dir = get_log_path()
        gnb = DeviceFactory.get_device(format(self.ssh_bts_hub.format(bts_id, hub_id)))
        rm = gnb.get_cmd(cmd_name="rm", cmd_params={"file": hub_log_dir, "options": '-rf'})
        rm()
        mkdir_cmd = gnb.get_cmd(cmd_name='mkdir', cmd_params={'path': hub_log_dir})
        mkdir_cmd()
        mv_cmd = gnb.get_cmd(cmd_name='mv', cmd_params={'src': log_file_name,
                                                        'dst': hub_log_dir})
        mv_cmd()
        download_files(local_dir=log_dir,
                       remote_file=log_file_name,
                       remote_dir=hub_log_dir,
                       device_name=self.ssh_bts_hub.format(bts_id, hub_id),
                       timeout=timeout)
        return log_dir

    @load_moler_configuration_from_tl()
    def start_tcpdump_on_hub(self, interface, capture_file, count=0, duration=0, background=False, timeout=300,
                             additional_options=None, bts_id=0, hub_id=0):
        """
        Start tcpdump collection on the selected interface of the HUB
        :param interface:       Interface on the HUB
        :param capture_file:    Name of the capture file
        :param count:           Number of packets to be captured
        :param duration:        Duration of tcpdump in seconds
        :param background:      Flag if tcpdump should run in the background
        :param timeout:         Timeout in seconds to be set for the tcpdump command
        :param additional_options: options be added to tcpdump command
        :param bts_id:          BTS ID - related to TestLine configuration
        :param hub_id:          HUB id - id related to Test Line configuration
        """

        hub = DeviceFactory.get_device(format(self.ssh_bts_hub.format(bts_id, hub_id)))
        start_tcpdump_on_device(device=hub, interface=interface, capture_file=capture_file, count=count,
                                duration=duration, background=background, timeout=timeout,
                                additional_options=additional_options)

    def stop_tcpdump_on_hub(self, bts_id=0, hub_id=0):
        """
        Keyword for stopping the tcpdump collection on the HUB
        :param bts_id:    BTS ID - related to TestLine configuration
        :param hub_id:    HUB id - id related to Test Line configuration
        """

        hub = DeviceFactory.get_device(format(self.ssh_bts_hub.format(bts_id, hub_id)))
        stop_tcpdump_on_device(device=hub)


@six.add_metaclass(Singleton)
class EnbAsirHubLog(AsirHubLog):
    """Class contains logs collecting keywords for eNB ASiR HUB"""

    bts_type = 'ENB'

    def __init__(self):
        """
        Constructor of EnbAsirHubLog class.
        """
        super(EnbAsirHubLog, self).__init__(bts_type=EnbAsirHubLog.bts_type)


@six.add_metaclass(Singleton)
class GnbAsirHubLog(AsirHubLog):
    """Class contains logs collecting keywords for gNB ASiR HUB"""

    bts_type = 'GNB'

    def __init__(self):
        """
        Constructor of GnbAsirHubLog class.
        """
        super(GnbAsirHubLog, self).__init__(bts_type=GnbAsirHubLog.bts_type)
